messages.content:
Write a single self-contained HTML file with a 3D animation using three.js. three.js r160 is available as an ES module at './three.module.js' -- import it with:
  import * as THREE from './three.module.js';
Scene: a low-poly 3D humanoid figure performs this exact cycle on a treadmill-style ground, side-on camera: stands still for 2 seconds, walks in place for 3 seconds (limbs swinging at walking pace), runs in place for 3 seconds (faster, larger limb swings, slight forward lean), then stands still again for 2 seconds. The 10-second cycle loops forever and must start immediately on load. Limb movement must clearly differ between walking and running. No external assets besides the three.js import. Output ONLY the HTML in one code block.

response.text:
```html
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>Low-Poly Humanoid Treadmill</title>
<style>
  * { margin: 0; padding: 0; box-sizing: border-box; }
  body { overflow: hidden; background: #1a1a2e; }
  canvas { display: block; }
  #phase {
    position: absolute; top: 20px; left: 50%; transform: translateX(-50%);
    font-family: 'Courier New', monospace; font-size: 22px;
    color: #e0e0e0; background: rgba(0,0,0,0.6); padding: 10px 28px;
    border-radius: 8px; letter-spacing: 2px; text-transform: uppercase;
    pointer-events: none;
  }
</style>
</head>
<body>
<div id="phase">Standing</div>
<script type="module">
import * as THREE from './three.module.js';

// ── Constants ──
const CYCLE = 10; // seconds
const T_STAND = 2, T_WALK = 3, T_RUN = 3;
const R2D = 180 / Math.PI;
const D2R = Math.PI / 180;

// ── Renderer / Scene / Camera ──
const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setSize(window.innerWidth, window.innerHeight);
renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
document.body.appendChild(renderer.domElement);

const scene = new THREE.Scene();
scene.background = new THREE.Color(0x1a1a2e);
scene.fog = new THREE.Fog(0x1a1a2e, 12, 25);

const camera = new THREE.PerspectiveCamera(50, window.innerWidth / window.innerHeight, 0.1, 50);
camera.position.set(0, 1.6, 5.5);
camera.lookAt(0, 1.0, 0);

// ── Lighting ──
const ambient = new THREE.AmbientLight(0x404060, 0.6);
scene.add(ambient);

const dirLight = new THREE.DirectionalLight(0xffeedd, 1.2);
dirLight.position.set(3, 6, 4);
dirLight.castShadow = true;
dirLight.shadow.mapSize.set(1024, 1024);
dirLight.shadow.camera.left = -5;
dirLight.shadow.camera.right = 5;
dirLight.shadow.camera.top = 5;
dirLight.shadow.camera.bottom = -2;
scene.add(dirLight);

const rimLight = new THREE.DirectionalLight(0x4488ff, 0.3);
rimLight.position.set(-3, 3, -2);
scene.add(rimLight);

// ── Materials ──
const skinMat = new THREE.MeshLambertMaterial({ color: 0xd4956b, flatShading: true });
const torsoMat = new THREE.MeshLambertMaterial({ color: 0x3a7bd5, flatShading: true });
const pantsMat = new THREE.MeshLambertMaterial({ color: 0x2c3e6b, flatShading: true });
const shoeMat = new THREE.MeshLambertMaterial({ color: 0x222222, flatShading: true });
const beltMat = new THREE.MeshLambertMaterial({ color: 0x111111, flatShading: true });

// ── Build Humanoid ──
function createLimb(radiusTop, radiusBottom, length, material) {
  const geo = new THREE.CylinderGeometry(radiusTop, radiusBottom, length, 6);
  geo.translate(0, -length / 2, 0);
  return new THREE.Mesh(geo, material);
}

function createBox(w, h, d, material) {
  const geo = new THREE.BoxGeometry(w, h, d);
  geo.translate(0, -h / 2, 0);
  return new THREE.Mesh(geo, material);
}

// Root
const root = new THREE.Group();
root.position.set(0, 0, 0);
scene.add(root);

// Torso (upper body)
const torso = new THREE.Group();
root.add(torso);

const torsoMesh = createBox(0.45, 0.55, 0.25, torsoMat);
torso.add(torsoMesh);

const beltMesh = createBox(0.47, 0.06, 0.27, beltMat);
beltMesh.position.y = -0.28;
torso.add(beltMesh);

// Head
const head = new THREE.Group();
head.position.y = 0.32;
torso.add(head);

const headMesh = new THREE.Mesh(
  new THREE.BoxGeometry(0.28, 0.30, 0.28),
  skinMat
);
headMesh.position.y = 0.15;
head.add(headMesh);

// Eyes (simple dots)
const eyeGeo = new THREE.BoxGeometry(0.04, 0.04, 0.01);
const eyeMat = new THREE.MeshBasicMaterial({ color: 0x111111 });
const leftEye = new THREE.Mesh(eyeGeo, eyeMat);
leftEye.position.set(-0.07, 0.2, 0.14);
head.add(leftEye);
const rightEye = new THREE.Mesh(eyeGeo, eyeMat);
rightEye.position.set(0.07, 0.2, 0.14);
head.add(rightEye);

// Upper Arms
function createArm(side) {
  const sign = side === 'left' ? 1 : -1;
  const shoulder = new THREE.Group();
  shoulder.position.set(sign * 0.28, 0.22, 0);
  torso.add(shoulder);

  // Shoulder sphere
  const shoulderBall = new THREE.Mesh(
    new THREE.SphereGeometry(0.07, 5, 4),
    torsoMat
  );
  shoulder.add(shoulderBall);

  const upperArm = createLimb(0.065, 0.055, 0.30, torsoMat);
  shoulder.add(upperArm);

  const elbow = new THREE.Group();
  elbow.position.y = -0.30;
  shoulder.add(elbow);

  const elbowBall = new THREE.Mesh(
    new THREE.SphereGeometry(0.05, 4, 3),
    skinMat
  );
  elbow.add(elbowBall);

  const forearm = createLimb(0.055, 0.045, 0.28, skinMat);
  elbow.add(forearm);

  // Hand
  const hand = new THREE.Mesh(
    new THREE.BoxGeometry(0.07, 0.08, 0.05),
    skinMat
  );
  hand.position.y = -0.30;
  elbow.add(hand);

  return { shoulder, elbow };
}

const leftArm = createArm('left');
const rightArm = createArm('right');

// Upper Legs
function createLeg(side) {
  const sign = side === 'left' ? 1 : -1;
  const hip = new THREE.Group();
  hip.position.set(sign * 0.12, -0.30, 0);
  root.add(hip);

  const hipBall = new THREE.Mesh(
    new THREE.SphereGeometry(0.08, 5, 4),
    pantsMat
  );
  hip.add(hipBall);

  const upperLeg = createLimb(0.08, 0.065, 0.40, pantsMat);
  hip.add(upperLeg);

  const knee = new THREE.Group();
  knee.position.y = -0.40;
  hip.add(knee);

  const kneeBall = new THREE.Mesh(
    new THREE.SphereGeometry(0.06, 4, 3),
    skinMat
  );
  knee.add(kneeBall);

  const lowerLeg = createLimb(0.065, 0.05, 0.38, skinMat);
  knee.add(lowerLeg);

  // Foot
  const foot = new THREE.Mesh(
    new THREE.BoxGeometry(0.10, 0.05, 0.22),
    shoeMat
  );
  foot.position.set(0, -0.38, 0.06);
  knee.add(foot);

  return { hip, knee };
}

const leftLeg = createLeg('left');
const rightLeg = createLeg('right');

// ── Treadmill Ground ──
const groundGroup = new THREE.Group();
scene.add(groundGroup);

// Main platform
const platformGeo = new THREE.BoxGeometry(2.4, 0.15, 1.2);
const platformMat = new THREE.MeshLambertMaterial({ color: 0x333344, flatShading: true });
const platform = new THREE.Mesh(platformGeo, platformMat);
platform.position.y = 0;
platform.receiveShadow = true;
groundGroup.add(platform);

// Belt surface
const beltGeo = new THREE.BoxGeometry(2.0, 0.02, 0.8);
const beltMat = new THREE.MeshLambertMaterial({ color: 0x555566, flatShading: true });
const belt = new THREE.Mesh(beltGeo, beltMat);
belt.position.y = 0.08;
belt.receiveShadow = true;
groundGroup.add(belt);

// Side rails
const railGeo = new THREE.BoxGeometry(2.2, 0.05, 0.06);
const railMat = new THREE.MeshLambertMaterial({ color: 0x444455, flatShading: true });
const leftRail = new THREE.Mesh(railGeo, railMat);
leftRail.position.set(0, 0.12, 0.42);
groundGroup.add(leftRail);
const rightRail = new THREE.Mesh(railGeo, railMat);
rightRail.position.set(0, 0.12, -0.42);
groundGroup.add(rightRail);

// Belt lines (to show movement)
const lineGroup = new THREE.Group();
groundGroup.add(lineGroup);
const lineMat = new THREE.MeshBasicMaterial({ color: 0x777788 });
for (let i = 0; i < 8; i++) {
  const lineGeo = new THREE.BoxGeometry(0.02, 0.005, 0.7);
  const line = new THREE.Mesh(lineGeo, lineMat);
  line.position.x = -0.9 + i * 0.27;
  line.position.y = 0.091;
  lineGroup.add(line);
}

// Front/back edges
const edgeGeo = new THREE.BoxGeometry(0.06, 0.12, 1.0);
const edgeMat = new THREE.MeshLambertMaterial({ color: 0x2a2a3a, flatShading: true });
const frontEdge = new THREE.Mesh(edgeGeo, edgeMat);
frontEdge.position.set(1.1, 0.06, 0);
groundGroup.add(frontEdge);
const backEdge = new THREE.Mesh(edgeGeo, edgeMat);
backEdge.position.set(-1.1, 0.06, 0);
groundGroup.add(backEdge);

// ── Animation ──
const phaseEl = document.getElementById('phase');

function getPhase(t) {
  const cycle = t % CYCLE;
  if (cycle < T_STAND) return 'stand';
  if (cycle < T_STAND + T_WALK) return 'walk';
  return 'run';
}

function getPhaseTime(t) {
  const cycle = t % CYCLE;
  if (cycle < T_STAND) return cycle;
  if (cycle < T_STAND + T_WALK) return cycle - T_STAND;
  return cycle - T_STAND - T_WALK;
}

// Smooth blend using cosine
function smoothStep(a, b, x) {
  const t = Math.max(0, Math.min(1, (x - a) / (b - a)));
  return t * t * (3 - 2 * t);
}

// Animate limbs
function animateLimb(hipAngle, kneeAngle, shoulderAngle, elbowAngle, lean) {
  // Left leg
  leftLeg.hip.rotation.x = hipAngle;
  leftLeg.knee.rotation.x = kneeAngle;

  // Right leg (opposite phase)
  rightLeg.hip.rotation.x = -hipAngle;
  rightLeg.knee.rotation.x = -kneeAngle;

  // Left arm
  leftArm.shoulder.rotation.x = shoulderAngle;
  leftArm.elbow.rotation.x = elbowAngle;

  // Right arm (opposite phase)
  rightArm.shoulder.rotation.x = -shoulderAngle;
  rightArm.elbow.rotation.x = -elbowAngle;

  // Forward lean
  torso.rotation.x = lean;
  root.rotation.x = lean * 0.3;
}

function animate(t) {
  const phase = getPhase(t);
  const pt = getPhaseTime(t);
  const cycle = t % CYCLE;

  // Belt animation
  const beltSpeed = phase === 'run' ? 2.0 : (phase === 'walk' ? 0.8 : 0);
  lineGroup.children.forEach((line) => {
    line.position.x -= beltSpeed * 0.016;
    if (line.position.x < -1.0) line.position.x += 2.16;
  });

  let hipA = 0, kneeA = 0, shoulderA = 0, elbowA = 0, lean = 0;

  if (phase === 'stand') {
    // Slight breathing animation
    const breathe = Math.sin(t * Math.PI * 0.5) * 0.02;
    lean = breathe;
    phaseEl.textContent = 'Standing';
  }
  else if (phase === 'walk') {
    const freq = 1.5; // steps per second
    const phaseAngle = t * freq * Math.PI * 2;

    // Walking: moderate limb swings
    hipA = Math.sin(phaseAngle) * 22 * D2R;
    kneeA = Math.max(0, Math.sin(phaseAngle + Math.PI)) * 35 * D2R;
    shoulderA = Math.sin(phaseAngle + Math.PI) * 20 * D2R;
    elbowA = Math.abs(Math.sin(phaseAngle + Math.PI)) * 25 * D2R;
    lean = 0;

    // Smooth transitions at start/end of walk
    const blendDur = 0.3;
    const walkDur = T_WALK;
    const blendIn = smoothStep(0, blendDur, pt);
    const blendOut = 1 - smoothStep(walkDur - blendDur, walkDur, pt);
    const blend = Math.min(blendIn, blendOut);
    hipA *= blend;
    kneeA *= blend;
    shoulderA *= blend;
    elbowA *= blend;

    phaseEl.textContent = 'Walking';
  }
  else if (phase === 'run') {
    const freq = 3.0; // faster steps per second
    const phaseAngle = t * freq * Math.PI * 2;

    // Running: larger limb swings, more knee bend, forward lean
    hipA = Math.sin(phaseAngle) * 42 * D2R;
    kneeA = Math.max(0, Math.sin(phaseAngle + Math.PI)) * 70 * D2R;
    shoulderA = Math.sin(phaseAngle + Math.PI) * 35 * D2R;
    elbowA = Math.abs(Math.sin(phaseAngle + Math.PI)) * 55 * D2R;
    lean = 8 * D2R; // slight forward lean

    // Smooth transitions at start/end of run
    const blendDur = 0.3;
    const runDur = T_RUN;
    const blendIn = smoothStep(0, blendDur, pt);
    const blendOut = 1 - smoothStep(runDur - blendDur, runDur, pt);
    const blend = Math.min(blendIn, blendOut);
    hipA *= blend;
    kneeA *= blend;
    shoulderA *= blend;
    elbowA *= blend;
    lean *= blend;

    phaseEl.textContent = 'Running';
  }

  animateLimb(hipA, kneeA, shoulderA, elbowA, lean);
}

// ── Render Loop ──
const clock = new THREE.Clock();

function render() {
  requestAnimationFrame(render);
  const t = clock.getElapsedTime();
  animate(t);
  renderer.render(scene, camera);
}

// ── Resize Handler ──
window.addEventListener('resize', () => {
  camera.aspect = window.innerWidth / window.innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(window.innerWidth, window.innerHeight);
});

// Start immediately
render();
</script>
</body>
</html>
```
